class TrieNode:
    def __init__(self):
        self.children = {}

def maximize_xor(nums, queries):
    nums.sort()
    indexed_queries = sorted(range(len(queries)), key=lambda i: queries[i][1])  # process queries by increasing limit
    root = TrieNode()
    results = [-1] * len(queries)
    num_index = 0

    def insert(num):
        node = root
        for bit in range(30, -1, -1):
            b = (num >> bit) & 1
            if b not in node.children:
                node.children[b] = TrieNode()
            node = node.children[b]

    def best_xor(x):
        node = root
        result = 0
        for bit in range(30, -1, -1):
            b = (x >> bit) & 1
            opposite = 1 - b
            if opposite in node.children:
                result |= (1 << bit)
                node = node.children[opposite]
            else:
                node = node.children[b]
        return result

    for q_index in indexed_queries:
        x, m = queries[q_index]
        while num_index < len(nums) and nums[num_index] <= m:
            insert(nums[num_index])                                   # only elements that now qualify are inserted
            num_index += 1
        if num_index > 0:
            results[q_index] = best_xor(x)
    return results


if __name__ == "__main__":
    print(maximize_xor([0, 1, 2, 3, 4], [[3, 1], [1, 3], [5, 6]]))

