vector<int> maximizeXor(vector<int>& nums, vector<vector<int>>& queries) {
    sort(nums.begin(), nums.end());
    int q = (int)queries.size();
    vector<int> order(q);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        return queries[a][1] < queries[b][1];                                // process queries by increasing limit
    });
    TrieNode* root = new TrieNode();
    vector<int> results(q, -1);
    int numIndex = 0;
    for (int qi : order) {
        int x = queries[qi][0], m = queries[qi][1];
        while (numIndex < (int)nums.size() && nums[numIndex] <= m) {
            TrieNode* node = root;
            for (int bit = 30; bit >= 0; bit--) {
                int b = (nums[numIndex] >> bit) & 1;
                if (!node->children[b]) node->children[b] = new TrieNode();
                node = node->children[b];
            }
            numIndex++;                                                        // only elements that now qualify are inserted
        }
        if (numIndex > 0) {
            TrieNode* node = root;
            int result = 0;
            for (int bit = 30; bit >= 0; bit--) {
